static int ttalink_test_common(uint8_t, uint8_t, ttalink_message_t *last_msg);

static int ttalink_test_all(uint8_t dst_addr, uint8_t src_addr, ttalink_message_t *last_msg)
{

    printf("########################\n");
    int err = ttalink_test_common(dst_addr, src_addr, last_msg);
    printf("########################\n");
    if(err==0){
	    printf("test c ttalink_test_all ok !\n");
    }else{
        printf("test c ttalink_test_all fail !\n");
    }
    printf("########################\n");
    return err;
}
