    packet1.ctrl_state = packet_in.ctrl_state;
    packet1.flight_time = packet_in.flight_time;
    packet1.simple_time = packet_in.simple_time;
    packet1.sn = packet_in.sn;
    packet1.upload_state = packet_in.upload_state;
