    int count = 0;
    ttalink_bms_data_t packet_in;
    if(ttalink_buffer_flag==TTALINK_BUFFER_FLAG_ALLONE){
        ttalink_allone_buffer(&packet_in, sizeof(packet_in));
    }else if(ttalink_buffer_flag==TTALINK_BUFFER_FLAG_ALLZERO){
        ttalink_allzero_buffer(&packet_in, sizeof(packet_in));
    }else{
        ttalink_random_buffer(&packet_in, sizeof(packet_in));
    }
    ttalink_bms_data_t packet1, packet2;
    memset(&packet1, 0, sizeof(packet1));
    packet1.update_time = packet_in.update_time;
    packet1.core_temperature = packet_in.core_temperature;
    packet1.plate_temperature = packet_in.plate_temperature;
    packet1.cell = packet_in.cell;
    packet1.voltage = packet_in.voltage;
    packet1.current = packet_in.current;
    packet1.bms_state = packet_in.bms_state;
    packet1.bms_addr = packet_in.bms_addr;
    packet1.remaining_capacity = packet_in.remaining_capacity;
    packet1.full_capacity = packet_in.full_capacity;
    packet1.charge_state = packet_in.charge_state;
    packet1.charging_voltage = packet_in.charging_voltage;
    
    tta_array_memcpy(packet1.voltage_cell, packet_in.voltage_cell, sizeof(uint16_t)*18);
