    packet1.year = packet_in.year;
    packet1.month = packet_in.month;
    packet1.date = packet_in.date;
    packet1.hour = packet_in.hour;
    packet1.minuter = packet_in.minuter;
    packet1.second = packet_in.second;
    packet1.unix_timestamp_ms = packet_in.unix_timestamp_ms;
    
    tta_array_memcpy(packet1.gps_param, packet_in.gps_param, sizeof(float)*4);
    

    // test 1
    memset(&packet2, 0, sizeof(packet2));
