    int count = 0;
    ttalink_stream_imu_t packet_in;
    if(ttalink_buffer_flag==TTALINK_BUFFER_FLAG_ALLONE){
        ttalink_allone_buffer(&packet_in, sizeof(packet_in));
    }else if(ttalink_buffer_flag==TTALINK_BUFFER_FLAG_ALLZERO){
        ttalink_allzero_buffer(&packet_in, sizeof(packet_in));
    }else{
        ttalink_random_buffer(&packet_in, sizeof(packet_in));
    }
    ttalink_stream_imu_t packet1, packet2;
    memset(&packet1, 0, sizeof(packet1));
    
    tta_array_memcpy(packet1.main_acc1, packet_in.main_acc1, sizeof(float)*3);
    tta_array_memcpy(packet1.main_acc2, packet_in.main_acc2, sizeof(float)*3);
    tta_array_memcpy(packet1.backup_acc, packet_in.backup_acc, sizeof(float)*3);
    tta_array_memcpy(packet1.main_gyro1, packet_in.main_gyro1, sizeof(float)*3);
    tta_array_memcpy(packet1.main_gyro2, packet_in.main_gyro2, sizeof(float)*3);
    tta_array_memcpy(packet1.backup_gyro, packet_in.backup_gyro, sizeof(float)*3);
    tta_array_memcpy(packet1.switch_acc, packet_in.switch_acc, sizeof(float)*3);
    tta_array_memcpy(packet1.switch_gyro, packet_in.switch_gyro, sizeof(float)*3);
    

