    ttalink_sensors_device_data_t packet1, packet2;
    memset(&packet1, 0, sizeof(packet1));
    packet1.update_time = packet_in.update_time;
    packet1.radar_latit = packet_in.radar_latit;
    packet1.radar_longi = packet_in.radar_longi;
    packet1.radar_altit = packet_in.radar_altit;
    packet1.radar_confidance = packet_in.radar_confidance;
    
    tta_array_memcpy(packet1.params, packet_in.params, sizeof(float)*4);
    

    // test 1
