    ttalink_channel_function_config_ack_decode(&msg, &packet2);
    if(msg.magic!=TTALINK_STX || msg.magic2!=TTALINK_STX2 || msg.ver_major!=TTALINK_VERSION_MAJOR || msg.dst_addr!=dst_addr || msg.src_addr!=src_addr || msg.msgid!=TTALINK_MSG_ID_CHANNEL_FUNCTION_CONFIG_ACK) {
        printf("test c ttalink_channel_function_config_ack encode_chan->decode cmp1 fail.\n");
        return -1;
    }
    cmp = memcmp(&packet1, &packet2, sizeof(packet1));
    if(cmp!=0) {
        printf("test c ttalink_channel_function_config_ack encode_chan->decode cmp2 fail.\n");
        return -1;
    }

    // test 8
    memset(&packet2, 0, sizeof(packet2));
    ttalink_to_send_buffer(buffer, &msg);
    cmp = 1;
    count = ttalink_get_send_buffer_length(&msg);
    for(i=0; i<count; i++) {
        //printf("%02x ", buffer[i]);
		if(ttalink_parse_char(TTALINK_CHANNEL_DEFAULT, buffer[i], &msg, &status)) {
			if(msg.msgid == TTALINK_MSG_ID_CHANNEL_FUNCTION_CONFIG_ACK && i==count-1) {
				ttalink_channel_function_config_ack_decode(&msg, &packet2);
                if(msg.magic!=TTALINK_STX || msg.magic2!=TTALINK_STX2 || msg.ver_major!=TTALINK_VERSION_MAJOR || msg.dst_addr!=dst_addr || msg.src_addr!=src_addr || msg.msgid!=TTALINK_MSG_ID_CHANNEL_FUNCTION_CONFIG_ACK) {
                    cmp = -1;
                } else {
				    cmp = memcmp(&packet1, &packet2, sizeof(packet1));
                }
			}
		}
	}
    //printf("\n");
    if(cmp!=0) {
        printf("test c ttalink_channel_function_config_ack to_send_buffer->parse fail.\n");
        return -1;
    }

    // test 9
    memset(&packet2, 0, sizeof(packet2));
