    if(msg.magic!=TTALINK_STX || msg.magic2!=TTALINK_STX2_NOCRC || msg.ver_major!=TTALINK_VERSION_MAJOR || msg.dst_addr!=dst_addr || msg.src_addr!=src_addr || msg.msgid!=TTALINK_MSG_ID_TEST_PWM_OUTPUT) {
        printf("test c ttalink_test_pwm_output pack_nocrc->decode cmp1 fail.\n");
        return -1;
    }
    cmp = memcmp(&packet1, &packet2, sizeof(packet1));
    if(cmp!=0) {
        printf("test c ttalink_test_pwm_output pack_nocrc->decode cmp2 fail.\n");
        return -1;
    }

    // test 3
    memset(&packet2, 0, sizeof(packet2));
    ttalink_test_pwm_output_pack_chan(dst_addr, src_addr, TTALINK_CHANNEL_DEFAULT, &msg , packet1.idx , packet1.value );
